 * This project uses @Incubating APIs which are subject to change.
 */

plugins {
    id("xyz.wagyourtail.unimined").version("1.4.41-kappa");
}

version = "1.1.0-1.12.2-forge";

base {
    archivesName.set("explosiveenhancement");
}

repositories {
    maven {
        url = uri("https://maven.cleanroommc.com");
    }

    exclusiveContent {
        forRepository {
            maven {
                name = "CurseMaven";
                url = uri("https://curse.cleanroommc.com");
            }
        }
        filter {
            includeGroup("curse.maven");
        }
    }
}

unimined.minecraft {
    version("1.12.2");

    mappings {
        mcp("stable", "39-1.12");
    }

    minecraftForge {
        loader("14.23.5.2864");
    }

    runs.all {
        args("--mixin", "explosiveenhancement.mixin.json");
    }

    defaultRemapJar = false;

    remap(tasks.named<Jar>("jar").get()) {
        mixinRemap {
            enableBaseMixin();
            enableMixinExtra();
        }
    }
}

dependencies {
    implementation("com.cleanroommc:configanytime:3.0");
    implementation("zone.rong:mixinbooter:11.17") {
        isTransitive = false;
    }
    // annotationProcessor("zone.rong:mixinbooter:11.17");

    "modImplementation"("curse.maven:oceanic-expanse-840576:7009970");
}

sourceSets {
    main {
        java {
            srcDir(rootProject.file("common/src/main/java"));
            srcDir("src/main/java");
        }
        resources {
            srcDir(rootProject.file("common/src/main/resources"));
            srcDir("src/main/resources");
        }
    }
}

tasks.withType<JavaCompile>().configureEach {
    options.release.set(8);
}

tasks.named<Jar>("jar").configure {
    manifest {
        attributes(
            "MixinConfigs" to "explosiveenhancement.mixin.json"
        );
    }

    finalizedBy("remapJar");
}
